function appendEditorToolItem(primary, when, order, alternative, precondition2, enableInCompactMode) {
  const item = {
    command: {
      id: primary.id,
      title: primary.title,
      icon: primary.icon,
      toggled: primary.toggled,
      precondition: precondition2
    },
    group: "navigation",
    when,
    order
  };
  if (alternative) {
    item.alt = {
      id: alternative.id,
      title: alternative.title,
      icon: alternative.icon
    };
  }
  MenuRegistry.appendMenuItem(MenuId.EditorTitle, item);
  if (enableInCompactMode) {
    MenuRegistry.appendMenuItem(MenuId.CompactWindowEditorTitle, item);
  }
}
